mapper.select:
SELECT email, day_of_week, time_slot
FROM tbl_babysitter_availability
WHERE email = #{email}

mapper.sql:
WHERE status = 'ACTIVE'

    AND region LIKE CONCAT('%', #{search.region}, '%')


    AND career_years >= #{search.minCareerYears}


    AND (name LIKE CONCAT('%', #{search.keyword}, '%')
         OR intro LIKE CONCAT('%', #{search.keyword}, '%'))


    AND EXISTS (
        SELECT 1 FROM tbl_babysitter_availability a
        WHERE a.email = tbl_babysitter_profile.email
          AND a.day_of_week = #{search.dayOfWeek}
          AND a.time_slot = #{search.timeSlot}
    )
